                continue
            nx, ny = sx + dx, sy + dy
            if not in_bounds(nx, ny) or (nx, ny) in obs:
                continue
            val = dist2(nx, ny, ox, oy) - 0.1 * (dx * dx + dy * dy)
            if val > best[2]:
                best = (dx, dy, val)
        return [best[0], best[1]] if best[2] != -10**18 else [0, 0]

    # opponent greedy target estimate
    def greedy_next(px, py):
        best_t = None
        best_d = 10**18
        for rx, ry in res:
            d = dist2(px, py, rx, ry)
            if d < best_d:
                best_d = d
                best_t = (rx, ry)
        if best_t is None:
            return (px, py)
        tx, ty = best_t
        best = (0, 0)
        bestv = -10**18
